// ============================================================================
// SAMPLE · Stripe → Airtable (Membership Revenue) — Classify + Shape
//
// DESIGN RULES THAT MUST NOT BE BROKEN (see _STRIPE_REVENUE_FEED_BUILD_SPEC):
//  1. Tier is resolved ONLY via the Stripe Price Map (price ID -> tier).
//     NEVER from charge amount, Stripe product, or price nickname. Amounts are
//     fee-uplifted inconsistently (+3.2% / +0.6% / 0%); the nickname
//     "SAMPLE Elite Membership @ 5000" sits on the Core Fellow product; and one
//     product serves two tiers.
//  2. An unmapped price is written as "⚠️ UNMAPPED" and raises a Sync
//     Exception. It is NEVER guessed and NEVER silently dropped.
//  3. Member counts are DISTINCT Stripe Customer IDs, never row counts —
//     one customer can hold several subscriptions (Al holds 2).
//  4. Payments come from PAID INVOICES, not charges. In this account charges
//     carry invoice=null and no price reference; only the invoice identifies
//     what was bought. Charges are matched in solely for fee/net + contactId.
// ============================================================================
const nowIso = new Date().toISOString();
const D = (ts) => new Date(ts * 1000).toISOString().slice(0, 10);
const pages = (n) => $(n).all().flatMap((i) => i.json.data || []);
const UNMAPPED = '⚠️ UNMAPPED';
const WF = 'SAMPLE · Stripe → Airtable (Membership Revenue)';

const invoices = pages('Stripe: Paid Invoices');
const charges  = pages('Stripe: Charges').filter((c) => c.status === 'succeeded');
const subs     = pages('Stripe: Subscriptions');

// ---- price map (the single place tier is decided) ----
const map = {};
for (const it of $('Airtable: Read Price Map').all()) {
  for (const r of (it.json.records || [])) {
    const f = r.fields || {};
    if (!f['Stripe Price ID']) continue;
    map[f['Stripe Price ID']] = {
      tier: f['Tier'] || UNMAPPED,
      cadence: f['Cadence'] || null,
      isMember: f['Counts as Membership'] === true,
    };
  }
}
if (Object.keys(map).length === 0) {
  throw new Error('Stripe Price Map is empty — refusing to run. Every tier would be UNMAPPED and every tile would be zeroed.');
}
const classify = (pid) => (pid && map[pid]) ? map[pid] : { tier: UNMAPPED, cadence: null, isMember: false };

const exceptions = [];
const seenExc = new Set();
const flag = (key, type, sev, detail, src) => {
  if (seenExc.has(key)) return;
  seenExc.add(key);
  exceptions.push({
    'Exception Key': key, 'Type': type, 'Severity': sev, 'Source Workflow': WF,
    'Detail': detail, 'Source Record': src, 'First Seen': nowIso,
    'Last Seen': nowIso, 'Resolved': false,
  });
};

// ---- charge lookup: customer + amount + same day ----
const chIdx = new Map();
for (const c of charges) chIdx.set(`${c.customer}|${c.amount}|${D(c.created)}`, c);
const contactIdOf = (c) => (c && c.payment_intent && typeof c.payment_intent === 'object'
  && c.payment_intent.metadata) ? (c.payment_intent.metadata.contactId || null) : null;

// ---- identity index: GHL contactId per Stripe customer ----
// GHL stamps contactId onto every PaymentIntent it creates, including the $39.97/$42.99
// application fees. So a customer whose membership payment predates GHL payment links
// (Al Fenoy, 2025-11-21, empty metadata) still resolves via a later charge on the SAME
// Stripe customer. Verified 2026-08-02: xlbkrkQlFsmCwKXvlpkJ = Al Fenoy in GHL.
const ghlByCustomer = {};
for (const c of charges) {
  const id = contactIdOf(c);
  if (id && c.customer && !ghlByCustomer[c.customer]) ghlByCustomer[c.customer] = id;
}

// ---- PAYMENTS: one row per paid invoice ----
const payments = [];
for (const inv of invoices) {
  const line = (inv.lines && inv.lines.data && inv.lines.data[0]) || {};
  const pid = (line.price && line.price.id)
    || (line.pricing && line.pricing.price_details && line.pricing.price_details.price) || null;
  const cls = classify(pid);
  if (cls.tier === UNMAPPED) {
    flag(`unmapped-price:${pid}`, 'Unmapped Price', '🔴 Blocks a number',
      `Paid invoice ${inv.id} uses Stripe price ${pid}, which has no row in Stripe Price Map. `
      + `Its revenue and tier are NOT counted until someone adds that row. `
      + `Do not infer the tier from the amount — add the price to the map.`, pid || inv.id);
  }
  const ch   = chIdx.get(`${inv.customer && inv.customer.id ? inv.customer.id : inv.customer}|${inv.amount_paid}|${D(inv.created)}`) || null;
  const bt   = (ch && typeof ch.balance_transaction === 'object') ? ch.balance_transaction : null;
  const cust = (inv.customer && typeof inv.customer === 'object') ? inv.customer : {};
  const custId = cust.id || inv.customer || null;
  // identity: this charge's contactId, else any charge on the same Stripe customer
  const ghl  = contactIdOf(ch) || (custId ? (ghlByCustomer[custId] || null) : null);
  const email = cust.email || inv.customer_email || null;
  if (!ghl && !email) {
    flag(`no-identity:${inv.id}`, 'Unresolved Identity', '🟡 Degrades a number',
      `Paid invoice ${inv.id} has no GHL contactId in payment_intent.metadata and no customer email, `
      + `so this payment cannot be joined to a contact.`, inv.id);
  }
  payments.push({
    'Stripe Invoice ID': inv.id,
    'Paid At': D(inv.created),
    'Gross Amount': (inv.amount_paid || 0) / 100,
    'Fee': bt ? bt.fee / 100 : null,
    'Net Amount': bt ? example.com / 100 : null,
    'Currency': (inv.currency || '').toUpperCase(),
    'Stripe Customer ID': custId,
    'Customer Name': cust.name || inv.customer_name || null,
    'Customer Email': email,
    'Stripe Price ID': pid,
    'Tier': cls.tier,
    'Counts as Membership': cls.isMember,
    'Matched Charge ID': ch ? ch.id : null,
    'GHL Contact ID': ghl,
    'Description': inv.description || line.description || null,
    'Last Synced': nowIso,
  });
}

// ---- MEMBERS: one row per subscription ----
const members = [];
for (const s of subs) {
  const price = (s.items && s.items.data && s.items.data[0] && s.items.data[0].price) || {};
  const pid = price.id || null;
  const cls = classify(pid);
  if (cls.tier === UNMAPPED) {
    flag(`unmapped-price:${pid}`, 'Unmapped Price', '🔴 Blocks a number',
      `Subscription ${s.id} uses Stripe price ${pid}, which has no row in Stripe Price Map. `
      + `This subscriber is NOT counted in paid members or ARR until that row is added.`, pid || s.id);
  }
  const cust = (s.customer && typeof s.customer === 'object') ? s.customer : {};
  const custId = cust.id || s.customer || null;
  const amt = (price.unit_amount || 0) / 100;
  const iv = (price.recurring && price.recurring.interval) || null;
  const ct = (price.recurring && price.recurring.interval_count) || 1;
  const perYear = iv === 'month' ? 12 / ct : iv === 'week' ? 52 / ct : iv === 'day' ? 365 / ct : 1 / ct;
  const SampleContact17239 = Math.round(amt * perYear * 100) / 100;
  members.push({
    'Stripe Subscription ID': s.id,
    'Stripe Customer ID': custId,
    'Customer Name': cust.name || null,
    'Customer Email': cust.email || null,
    'Status': s.status,
    'Stripe Price ID': pid,
    'Tier': cls.tier,
    'Cadence': cls.cadence || (iv === 'month' ? 'Monthly' : iv === 'year' ? 'Annual' : null),
    'Unit Amount': amt,
    'Annualized Value': SampleContact17239,
    'Is Active Paid Member': s.status === 'active' && cls.isMember,
    'Current Period Start': s.current_period_start ? D(s.current_period_start) : null,
    'Current Period End': s.current_period_end ? D(s.current_period_end) : null,
    'Started At': s.start_date ? D(s.start_date) : null,
    'Canceled At': s.canceled_at ? D(s.canceled_at) : null,
    'GHL Contact ID': (custId && ghlByCustomer[custId]) || null,
    'Last Synced': nowIso,
  });
}

// ---- THE THREE MEASURES (never conflate these) ----
const active    = members.filter((m) => m['Is Active Paid Member']);
const distinct  = (rows) => new Set(rows.map((m) => m['Stripe Customer ID']).filter(Boolean)).size;
const collected = Math.round(payments.filter((p) => p['Counts as Membership'])
                    .reduce((s, p) => s + p['Gross Amount'], 0) * 100) / 100;
const arr       = Math.round(active.reduce((s, m) => s + m['Annualized Value'], 0) * 100) / 100;
const paidCount = distinct(active);
const byTier    = (t) => distinct(active.filter((m) => m['Tier'] === t));

// Guardrail: never let a failed/empty Stripe read silently zero a live tile.
if (invoices.length === 0 && subs.length === 0) {
  throw new Error('Stripe returned zero invoices AND zero subscriptions — refusing to write, this would zero the CEO tiles.');
}

const tiles = [
  { id: 'EXAMPLE_AIRTABLE_ID_5995E358AB', fields: { 'Actual': collected,
      'Why Status?': `Collected to date, auto-fed from Stripe paid invoices (last sync ${nowIso}). `
        + `This is money actually received — NOT the $${arr.toLocaleString()} ARR run-rate, and NOT `
        + `members × $5,000. Tier comes from the Stripe Price Map, never from the charge amount.` } },
  { id: 'EXAMPLE_AIRTABLE_ID_860149720A', fields: { 'Actual': byTier('3 · Core ($5k)') } },
  { id: 'EXAMPLE_AIRTABLE_ID_2FB4AC8234', fields: { 'Actual': byTier('2 · Catalyst ($1k)') } },
  { id: 'EXAMPLE_AIRTABLE_ID_1EE9AE5F36', fields: { 'Actual': byTier('4 · Circle ($10k)') } },
  { id: 'EXAMPLE_AIRTABLE_ID_7BC08C558A', fields: { 'Actual': paidCount } },
];

return [{ json: { members, payments, exceptions, tiles,
  measures: { collected, arr, paidCount,
    invoices: invoices.length, charges: charges.length, subs: subs.length,
    unmapped: exceptions.filter((e) => e.Type === 'Unmapped Price').length } } }];

const src = $('Classify + Shape').first().json.members || [];
const chunk = (a, n) => { const o = []; for (let i = 0; i < a.length; i += n) o.push(a.slice(i, i + n)); return o; };
return chunk(src, 10).map((b) => ({ json: {
  records: b.map((f) => ({ fields: f })),
  performUpsert: { fieldsToMergeOn: ['Stripe Subscription ID'] },
  typecast: true,
} }));

const src = $('Classify + Shape').first().json.payments || [];
const chunk = (a, n) => { const o = []; for (let i = 0; i < a.length; i += n) o.push(a.slice(i, i + n)); return o; };
return chunk(src, 10).map((b) => ({ json: {
  records: b.map((f) => ({ fields: f })),
  performUpsert: { fieldsToMergeOn: ['Stripe Invoice ID'] },
  typecast: true,
} }));

const src = $('Classify + Shape').first().json.exceptions || [];
const chunk = (a, n) => { const o = []; for (let i = 0; i < a.length; i += n) o.push(a.slice(i, i + n)); return o; };
return chunk(src, 10).map((b) => ({ json: {
  records: b.map((f) => ({ fields: f })),
  performUpsert: { fieldsToMergeOn: ['Exception Key'] },
  typecast: true,
} }));
